button.raw:
if camera?.running == true {
  camera?.stop()
} else {
  let c = camera ?? NativeMirrorController()
  camera = c
  Task { await c.start() }
}

cameraStartTask?.cancel()
cameraStartTask = nil
if camera?.running == true {
  camera?.stop()
} else {
  let c = camera ?? NativeMirrorController()
  camera = c
  cameraStartTask = Task { await c.start() }
}

phase.selected:
if phase == .background {
  cameraStartTask?.cancel()
  cameraStartTask = nil
  camera?.stop()
}
